package cn.linkdeck.adb;
import java.io.*;import java.util.*;import java.security.*;import javax.crypto.*;import org.json.*;
public class CompatibilityChecks {
 static int n;static void ok(boolean value,String msg){if(!value)throw new AssertionError(msg);n++;System.out.println("PASS: "+msg);}
 static final String props="[ro.build.version.sdk]: [22]\n[ro.product.model]: [QA TV]\n[ro.product.brand]: [coocaa]\n[ro.product.cpu.abi]: [arm64-v8a]\n[ro.serialno]: [PRIVATE_SERIAL]\n[ro.build.fingerprint]: [PRIVATE_FINGERPRINT]\n";
 static class Peer implements DeviceCapabilities.Device{List<String> commands=new ArrayList<>();boolean missing,deny,changed,fail;int getprops;public boolean connected(){return true;}public AdbClient.Result shell(String c)throws Exception{commands.add(c);if(fail&&commands.size()>3)throw new IOException("private error 192.168.31.120 SECRET_CODE");if(c.equals("getprop"))return new AdbClient.Result((changed&&getprops++>0?props.replace("PRIVATE_FINGERPRINT","CHANGED"):props),0);if(c.startsWith("command -v"))return new AdbClient.Result(missing?"":"/system/bin/"+c.substring(11),missing?1:0);if(c.equals("pm list packages"))return new AdbClient.Result(deny?"Permission denied":"package:android\npackage:test.app",deny?1:0);if(c.equals("pm help"))return new AdbClient.Result("pm install [-r] PATH\npm uninstall PACKAGE",0);if(c.equals("ls -d /sdcard"))return new AdbClient.Result("/sdcard",0);if(c.equals("dumpsys accessibility"))return new AdbClient.Result("User state[attributes:{id=0, currentUser=true}",0);throw new AssertionError("Unexpected or mutating probe: "+c);}}
 static void packet(java.io.OutputStream out,String code,int a,int b,byte[] data)throws Exception{int c=AdbClient.code(code),sum=0;for(byte x:data)sum+=x&255;java.nio.ByteBuffer h=java.nio.ByteBuffer.allocate(24).order(java.nio.ByteOrder.LITTLE_ENDIAN);h.putInt(c).putInt(a).putInt(b).putInt(data.length).putInt(sum).putInt(c^-1);out.write(h.array());out.write(data);out.flush();}
 static void trustBeforeCommands(AdbIdentity identity)throws Exception{
  try(java.net.ServerSocket server=new java.net.ServerSocket(0)){final Throwable[] error={null};final boolean[] verified={false},noOpen={false};Thread peer=new Thread(()->{try(java.net.Socket socket=server.accept()){socket.setSoTimeout(4000);DataInputStream in=new DataInputStream(socket.getInputStream());byte[] header=new byte[24];in.readFully(header);byte[] banner=new byte[AdbClient.integer(header,12)];in.readFully(banner);packet(socket.getOutputStream(),"STLS",0x1000000,0,new byte[0]);in.readFully(header);if(AdbClient.integer(header,0)!=AdbClient.code("STLS"))throw new AssertionError("missing STLS response");packet(socket.getOutputStream(),"CNXN",0x1000000,4096,"device::\0".getBytes("UTF-8"));noOpen[0]=in.read()==-1;}catch(Throwable e){error[0]=e;}});peer.start();
   final AdbClient[] client={null};client[0]=new AdbClient(new AdbClient.TlsUpgrade(){public java.net.Socket upgrade(java.net.Socket plain,String h,int port,AdbIdentity key){return plain;}public void verify(java.net.Socket established)throws Exception{verified[0]=!client[0].isConnected();throw new IOException("approval required fixture");}});
   try{client[0].connect("127.0.0.1",server.getLocalPort(),identity);throw new AssertionError("unapproved transport connected");}catch(AdbClient.ConnectionFailure expected){}finally{client[0].close();}peer.join(5000);if(error[0]!=null)throw new AssertionError(error[0]);ok(verified[0],"peer verification occurs after CNXN and before connected state");ok(noOpen[0],"unapproved encrypted transport sends no command OPEN");
  }
 }
 public static void main(String[] args)throws Exception{
  Peer peer=new Peer();DeviceCapabilities.Snapshot snapshot=DeviceCapabilities.inspect(peer,"传统 ADB");ok(!snapshot.partial&&snapshot.sdk==22,"old Android metadata accepted");ok(snapshot.items.get(DeviceCapabilities.REMOTE).state==DeviceCapabilities.State.READY,"command availability is not an observed key effect");ok(snapshot.items.get(DeviceCapabilities.INSTALL).state==DeviceCapabilities.State.READY,"installer presence does not claim an installation succeeded");ok(snapshot.items.get(DeviceCapabilities.DESKTOP).state==DeviceCapabilities.State.LIMITED,"desktop modifications never automatically certified");ok(peer.commands.stream().noneMatch(s->s.contains("keyevent")||s.contains("settings put")||s.startsWith("pm install")||s.contains("screencap -p")||s.startsWith("mkdir")),"probe has no writes, key injection or screenshot acquisition");snapshot.success(DeviceCapabilities.SCREENSHOT);ok(snapshot.items.get(DeviceCapabilities.SCREENSHOT).state==DeviceCapabilities.State.SUCCEEDED,"explicit successful operation can update its capability");
  String report=snapshot.export();ok(!report.contains("PRIVATE_SERIAL")&&!report.contains("PRIVATE_FINGERPRINT")&&!report.contains("192.168"),"default report omits identity and endpoint");snapshot.model="PRIVATE_SERIAL 192.168.31.120:5555 aa:bb:cc:dd:ee:ff fe80::abcd";report=snapshot.export();ok(!report.contains("PRIVATE_SERIAL")&&!report.contains("192.168")&&!report.contains("aa:bb")&&!report.contains("fe80"),"identifiers inside descriptive fields are also redacted");ok(!report.contains("pm help")&&!report.contains("SECRET_CODE"),"report contains no raw output or exception text");
  Peer absent=new Peer();absent.missing=true;DeviceCapabilities.Snapshot none=DeviceCapabilities.inspect(absent,"传统 ADB");ok(none.blocked(DeviceCapabilities.REMOTE)&&none.blocked(DeviceCapabilities.SCREENSHOT),"definitively missing tools block only their operations");Peer denied=new Peer();denied.deny=true;DeviceCapabilities.Snapshot limited=DeviceCapabilities.inspect(denied,"传统 ADB");ok(limited.items.get(DeviceCapabilities.APPS).state==DeviceCapabilities.State.LIMITED,"permission denied is not declared unsupported");Peer interrupted=new Peer();interrupted.fail=true;DeviceCapabilities.Snapshot partial=DeviceCapabilities.inspect(interrupted,"传统 ADB");ok(partial.partial&&partial.items.get(DeviceCapabilities.REMOTE).state==DeviceCapabilities.State.UNKNOWN,"interrupted detection does not certify earlier results");Peer changed=new Peer();changed.changed=true;ok(DeviceCapabilities.inspect(changed,"传统 ADB").partial,"firmware changes invalidate a mixed snapshot");
  File dir=new File(System.getProperty("java.io.tmpdir"),"linkdeck-tls-test-"+UUID.randomUUID());AdbIdentity identity=new AdbIdentity(dir);java.security.cert.X509Certificate cert=TlsIdentity.certificate(identity,dir);cert.verify(identity.publicKey());ok(cert.getPublicKey().equals(identity.publicKey()),"TLS certificate uses the existing ADB key");ok(Arrays.equals(cert.getEncoded(),TlsIdentity.certificate(new AdbIdentity(dir),dir).getEncoded()),"TLS identity persists across process-style reloads");
  String modern="currentUserId=0\nUser state[\n attributes:{id=0, magnificationModes={0=1}, installedServiceCount=0}\n services:{}]";
  ok(DesktopAssistant.activeUser(modern)==0,"modern currentUserId with matching user block is recognized");
  ok(DesktopAssistant.activeUser(modern.replace("currentUserId=0","currentUserId=10"))==-1,"modern header without matching user block remains unknown");
  ok(DesktopAssistant.activeUser(modern+"\ncurrentUserId=0")==-1,"duplicate current-user headers are rejected");
  ok(DesktopAssistant.activeUser(modern.replace("id=0,","id=0, currentUser=false,"))==-1,"contradictory current-user markers are rejected");
  ok(DesktopAssistant.activeUser(modern+"\nUser state[attributes:{id=10, currentUser=true}") == -1,"old and modern current-user disagreement stops changes");
  ok(DeviceCapabilities.featureFor("读取安装包路径").equals(DeviceCapabilities.APPS),"read-only APK path lookup is not gated by installation permissions");
  trustBeforeCommands(identity);
  System.out.println("COMPATIBILITY CORE PASSED: "+n+" checks.");
 }
}
